#include <stdio.h>
int main(void)
{
    int a[3][3]={{0,1,1},{1,0,1},{1,1,0}},colour[3]={0,-1,-1};
    int q[3]={0},h=0,t=1,ok=1;
    while(h<t) {
        int u=q[h++];
        for(int v=0;v<3;v++) {
            if(!a[u][v]) { continue; }
            if(colour[v]==-1) { colour[v]=1-colour[u];q[t++]=v; }
            else if(colour[v]==colour[u]) { ok=0; }
        }
    }
    (void)ok;
    printf("%d\n",ok);
    return 0;
}

